/**
 * Standalone Offline Markdown Parser & GFM Renderer for e-webui
 * Provides full CommonMark and GitHub Flavored Markdown support:
 * Headings (h1-h6), GFM Tables with alignments, Blockquotes, Ordered/Unordered Lists,
 * Bold, Italic, Strikethrough, Links, Inline Code, and Syntax-highlighted Code Blocks
 * with streaming resilience and strict HTML sanitization.
 */
(function (global) {
  "use strict";

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function parseMarkdown(text) {
    if (!text) return "";

    let src = String(text).replace(/\r\n/g, "\n").replace(/\r/g, "\n");

    // 1. Protect code blocks (support both closed and streaming unclosed fences)
    const codeBlocks = [];
    src = src.replace(/(?:^|\n)```([a-zA-Z0-9_+-]*)\n([\s\S]*?)(?:```(?:\n|$)|$)/g, function (match, lang, code) {
      const id = "\n\n%%%CODEBLOCK" + codeBlocks.length + "%%%\n\n";
      codeBlocks.push({ lang: (lang || "").trim(), code: code || "" });
      return id;
    });

    // 2. Protect inline code snippets
    const inlineCodes = [];
    src = src.replace(/`([^`\n]+)`/g, function (match, code) {
      const id = "%%%INLINECODE" + inlineCodes.length + "%%%";
      inlineCodes.push(code);
      return id;
    });

    // 3. Escape raw HTML tags (disarm scripts, iframes, handlers)
    src = src.replace(/</g, "&lt;");
    // Escape > except when it is at the start of a line indicating a blockquote
    src = src.replace(/(^|\n)>/g, "$1%%%BLOCKQUOTE_START%%%");
    src = src.replace(/>/g, "&gt;");
    src = src.replace(/%%%BLOCKQUOTE_START%%%/g, ">");

    // Inline formatting helper
    function parseInline(str) {
      let s = str;
      // Bold + Italic
      s = s.replace(/\*\*\*([^*]+)\*\*\*/g, "<strong><em>$1</em></strong>");
      // Bold
      s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
      s = s.replace(/__([^_]+)__/g, "<strong>$1</strong>");
      // Italic
      s = s.replace(/\*([^*\n]+)\*/g, "<em>$1</em>");
      s = s.replace(/(^|\s)_([^_]+)_(\s|$)/g, "$1<em>$2</em>$3");
      // Strikethrough
      s = s.replace(/~~([^~]+)~~/g, "<del>$1</del>");
      // Links (with protocol allowlist and XSS sanitization)
      s = s.replace(/\[([^\]]+)\]\(((?:[^()]+|\([^()]*\))+)\)/g, function (m, txt, url) {
        const cleanUrl = (url || "").trim();
        // Allow http://, https://, mailto:, and relative paths (/path but not //protocol-relative)
        const isSafe = /^(https?:\/\/|mailto:|\/(?!\/))/i.test(cleanUrl);
        const safeUrl = isSafe ? escapeHtml(cleanUrl) : "#";
        const safeText = escapeHtml(txt);
        return '<a href="' + safeUrl + '" target="_blank" rel="noopener noreferrer">' + safeText + '</a>';
      });
      return s;
    }

    // 4. Tables (GFM pipe tables with header, alignment, and cells)
    const tableRegex = /(?:^|\n)((?:\|[^\n]+\|\r?\n?)+)/g;
    src = src.replace(tableRegex, function (match, tableBlock) {
      const lines = tableBlock.trim().split("\n").map(function (l) { return l.trim(); }).filter(Boolean);
      if (lines.length < 2) return match;

      function parseRow(line) {
        return line.split("|").slice(1, -1).map(function (c) { return c.trim(); });
      }

      const sepCells = parseRow(lines[1]);
      const isSep = sepCells.length > 0 && sepCells.every(function (c) { return /^:?-+:?$/.test(c); });
      if (!isSep) return match;

      const aligns = sepCells.map(function (c) {
        const left = c.charAt(0) === ":";
        const right = c.charAt(c.length - 1) === ":";
        if (left && right) return "center";
        if (right) return "right";
        return "left";
      });

      const headerCells = parseRow(lines[0]);
      let html = '<div class="table-wrapper"><table><thead><tr>';
      headerCells.forEach(function (c, i) {
        const align = aligns[i] ? ' style="text-align:' + aligns[i] + '"' : "";
        html += '<th' + align + '>' + parseInline(c) + '</th>';
      });
      html += '</tr></thead><tbody>';

      for (let i = 2; i < lines.length; i++) {
        const rowCells = parseRow(lines[i]);
        html += '<tr>';
        for (let j = 0; j < headerCells.length; j++) {
          const val = rowCells[j] !== undefined ? rowCells[j] : "";
          const align = aligns[j] ? ' style="text-align:' + aligns[j] + '"' : "";
          html += '<td' + align + '>' + parseInline(val) + '</td>';
        }
        html += '</tr>';
      }
      html += '</tbody></table></div>';
      return "\n\n" + html + "\n\n";
    });

    // 5. Blockquotes
    src = src.replace(/(?:^|\n)((?:>[^\n]*(?:\n|$))+)/g, function (match, bqBlock) {
      const cleanLines = bqBlock.split("\n")
        .map(function (l) { return l.replace(/^>\s?/, ""); })
        .join("\n").trim();
      return "\n\n<blockquote>" + parseInline(cleanLines) + "</blockquote>\n\n";
    });

    // 6. Headings (H1 to H6)
    src = src.replace(/^(#{1,6})\s+(.+)$/gm, function (match, hashes, content) {
      const level = hashes.length;
      return "<h" + level + ">" + parseInline(content.trim()) + "</h" + level + ">";
    });

    // 7. Horizontal Rules
    src = src.replace(/^(?:---|\*\*\*|___)\s*$/gm, "<hr>");

    // 8. Unordered Lists
    src = src.replace(/(?:^|\n)((?:[ \t]*[-*+]\s+[^\n]+(?:\n|$))+)/g, function (match, listBlock) {
      const items = listBlock.trim().split("\n").map(function (l) {
        const text = l.replace(/^[ \t]*[-*+]\s+/, "");
        return "<li>" + parseInline(text) + "</li>";
      }).join("");
      return "\n\n<ul>" + items + "</ul>\n\n";
    });

    // 9. Ordered Lists
    src = src.replace(/(?:^|\n)((?:[ \t]*\d+\.\s+[^\n]+(?:\n|$))+)/g, function (match, listBlock) {
      const items = listBlock.trim().split("\n").map(function (l) {
        const text = l.replace(/^[ \t]*\d+\.\s+/, "");
        return "<li>" + parseInline(text) + "</li>";
      }).join("");
      return "\n\n<ol>" + items + "</ol>\n\n";
    });

    // 10. Standard inline formatting on remaining content
    src = parseInline(src);

    // 11. Paragraphs & Line Breaks
    const paragraphs = src.split(/\n\s*\n/);
    src = paragraphs.map(function (p) {
      p = p.trim();
      if (!p) return "";
      if (/^<(h[1-6]|ul|ol|li|blockquote|div|hr|table|thead|tbody|tr|th|td)/i.test(p) || p.startsWith("%%%CODEBLOCK")) {
        return p;
      }
      return "<p>" + p.replace(/\n/g, "<br>") + "</p>";
    }).filter(Boolean).join("\n\n");

    // 12. Restore inline code
    src = src.replace(/%%%INLINECODE(\d+)%%%/g, function (match, idx) {
      return "<code>" + escapeHtml(inlineCodes[Number(idx)]) + "</code>";
    });

    // 13. Restore code blocks with modern header and copy trigger
    src = src.replace(/%%%CODEBLOCK(\d+)%%%/g, function (match, idx) {
      const item = codeBlocks[Number(idx)];
      const lang = item.lang || "code";
      const escapedCode = escapeHtml(item.code.replace(/\n$/, ""));
      return '<div class="code-block-wrapper">' +
        '<div class="code-block-header">' +
          '<span class="code-lang">' + escapeHtml(lang) + '</span>' +
          '<button class="copy-code-btn" type="button" aria-label="Copy code snippet">' +
            '<svg class="code-copy-icon" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
              '<rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>' +
              '<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>' +
            '</svg>' +
            '<span class="copy-label">Copy</span>' +
          '</button>' +
        '</div>' +
        '<pre><code class="language-' + escapeHtml(lang) + '">' + escapedCode + '</code></pre>' +
      '</div>';
    });

    return src;
  }

  const marked = {
    parse: parseMarkdown
  };

  if (typeof module !== "undefined" && module.exports) {
    module.exports = marked;
  } else {
    global.marked = marked;
  }
})(typeof window !== "undefined" ? window : globalThis);
